FCharacterRow USproutDataLibrary::GetCharacterRow(int32 Key, bool& bFound)
{
    const FCharacterRow* Found = FSproutData::Character().FindById(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FCharacterRow();
}

int32 USproutDataLibrary::GetCharacterRowCount()
{
    return FSproutData::Character().Records().Num();
}

FCharacterRow USproutDataLibrary::GetCharacterRowAt(int32 Position, bool& bFound)
{
    const TArray<FCharacterRow>& Rows = FSproutData::Character().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FCharacterRow();
}


